import PackageDescription
import Foundation

// Generated by tools/package-lan-v2.py after all native link gates. A clean
// checkout without these local artifacts keeps the LAN feature unavailable.
let lanPath = "../FlashLAN/artifacts/apple/CFlashLAN.xcframework"
let lanPresent = FileManager.default.fileExists(atPath:
    URL(fileURLWithPath: #filePath).deletingLastPathComponent().appendingPathComponent(lanPath).path)
let lanTargets: [Target] = lanPresent ? [.binaryTarget(name: "CFlashLAN", path: lanPath)] : []

/// macOS 与 iOS 共用的数据层与设计语言。
/// - FlashCore：模型、SwiftData 实体与仓储、备份/LAN、领域纯函数、展示层 ViewModel
/// - FlashDesign：设计令牌、动效、品牌色与共用 SwiftUI 组件
let package = Package(
    name: "FlashKit",
    platforms: [.macOS(.v15), .iOS(.v18)],
    products: [
        .library(name: "FlashCore", targets: ["FlashCore"]),
        .library(name: "FlashDesign", targets: ["FlashDesign"]),
    ],
    targets: [
        .target(name: "FlashCore", dependencies: lanPresent ? [.target(name: "CFlashLAN")] : []),
        .target(name: "FlashDesign", dependencies: ["FlashCore"], resources: [.process("Resources")]),
        .testTarget(name: "FlashCoreTests", dependencies: ["FlashCore"]),
        .testTarget(name: "FlashDesignTests", dependencies: ["FlashDesign", "FlashCore"]),
    ] + lanTargets
)
